import base64

_SRC = ""


def apply():
    import sys
    M = sys.modules.get('moduli.richieste_remote')
    if M is None:
        try:
            import moduli.richieste_remote as M  # noqa
        except Exception:
            print('[RR112] richieste_remote non presente (ok)')
            return False
    C = getattr(M, 'RichiesteRemote', None)
    if C is None:
        return True
    try:
        src = base64.b64decode(_SRC).decode('utf-8')
        g = M.__dict__
        exec(compile(src, 'rr112', 'exec'), g)
        C.apri_finestra = g['apri_finestra']
        C.inserisci_brano = g['inserisci_brano']
        print('[RR112] Richieste Remote: usa il percorso della richiesta all inserimento (a caldo)')
        return True
    except Exception as e:
        print('[RR112] errore:', e)
        return False


try:
    apply()
except Exception as _e:
    print('patch 112: %s' % _e)
